void build(const string& s, const vector<string>& words, size_t start, const vector<bool>& reachable, string& sentence, vector<string>& out) {
    if (start == s.size()) {
        out.push_back(sentence);
        return;
    }
    for (const string& word : words) {
        size_t next = start + word.size();
        if (next <= s.size() && reachable[next] && s.compare(start, word.size(), word) == 0) {
            size_t before = sentence.size();
            if (!sentence.empty()) {
                sentence += ' ';
            }
            sentence += word;
            build(s, words, next, reachable, sentence, out);
            sentence.resize(before);
        }
    }
}

vector<string> word_break_sentences(string s, vector<string> words) {
    size_t n = s.size();
    // reachable[i]: the rest of s from position i can be split into words.
    vector<bool> reachable(n + 1, false);
    reachable[n] = true;
    for (size_t start = n; start-- > 0;) {
        for (const string& word : words) {
            size_t next = start + word.size();
            if (next <= n && reachable[next] && s.compare(start, word.size(), word) == 0) {
                reachable[start] = true;
                break;
            }
        }
    }
    vector<string> out;
    string sentence;
    if (reachable[0]) {
        build(s, words, 0, reachable, sentence, out);
    }
    sort(out.begin(), out.end());
    return out;
}

